  if (nums.some(v => v < 0 || v > 100000)) return 'Each value of nums is between 0 and 10^5.';
  if (k < 0 || k > 100000) return 'k is between 0 and 10^5.';
  if (op1 < 0 || op1 > nums.length) return 'op1 is between 0 and nums.length.';
  if (op2 < 0 || op2 > nums.length) return 'op2 is between 0 and nums.length.';
  return null;
}

