function minArraySum(nums, k, op1, op2) {
  // dp[a][b]: smallest sum of the numbers seen so far using at most a halvings and b subtractions.
  const dp = Array.from({ length: op1 + 1 }, () => new Array(op2 + 1).fill(0));

  for (const x of nums) {
    const half = Math.ceil(x / 2);
    const minus = x >= k ? x - k : Infinity;
    let both = Infinity;
    if (half >= k) {
      both = half - k;
    } else if (x >= k) {
      both = Math.ceil((x - k) / 2);
    }
    for (let a = op1; a >= 0; a--) {
      for (let b = op2; b >= 0; b--) {
        let best = dp[a][b] + x;
        if (a > 0) {
          best = Math.min(best, dp[a - 1][b] + half);
        }
        if (b > 0) {
          best = Math.min(best, dp[a][b - 1] + minus);
        }
        if (a > 0 && b > 0) {
          best = Math.min(best, dp[a - 1][b - 1] + both);
        }
        dp[a][b] = best;
      }
    }
  }
  return dp[op1][op2];
}

