function minArraySum(nums, k, op1, op2) {
  // Try every treatment of every index, applying the operations literally and checking
  // the subtraction's condition on the value it is applied to.
  const halve = v => Math.ceil(v / 2);
  let best = Infinity;
  const search = (i, left1, left2, sum) => {
    if (i === nums.length) {
      best = Math.min(best, sum);
      return;
    }
    const v = nums[i];
    search(i + 1, left1, left2, sum + v);
    if (left1 > 0) search(i + 1, left1 - 1, left2, sum + halve(v));
    if (left2 > 0 && v >= k) search(i + 1, left1, left2 - 1, sum + v - k);
    if (left1 > 0 && left2 > 0 && halve(v) >= k) search(i + 1, left1 - 1, left2 - 1, sum + halve(v) - k);
    if (left1 > 0 && left2 > 0 && v >= k) search(i + 1, left1 - 1, left2 - 1, sum + halve(v - k));
  };
  search(0, op1, op2, 0);
  return best;
}

