function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 100;
    const nums = Array.from({ length: n }, () => int(0, 100000));
    return [nums, int(0, 60000), int(n - 20, n), int(n - 20, n)];
  }
  const n = int(1, 7);
  const top = rand() < 0.7 ? 20 : 100000;
  const nums = Array.from({ length: n }, () => int(0, top));
  const k = rand() < 0.15 ? 0 : int(1, top === 20 ? 15 : 100000);
  return [nums, k, int(0, n), int(0, n)];
}
